// ============================================================
// @route   GET /api/billing/advances
// @desc    Trips not yet billed — open bookings an advance can be taken
//          for — and advances that need a decision (on a cancelled trip).
// ============================================================
exports.getAdvances = async (req, res, next) => {
  try {
    const open = await Trip.find({ status: { $in: ['booked', 'dispatched', 'en_route'] } })
      .select('tripNumber patientName status scheduleType scheduleDate estimatedFare grandTotal createdAt')
      .sort({ createdAt: -1 }).limit(200).lean();
    const unbilled = await Payment.find({ bill: null }).sort({ receivedAt: 1 });
    const extraIds = [...new Set(unbilled.map((p) => String(p.trip)))].filter((id) => !open.some((t) => String(t._id) === id));
    const extra = extraIds.length
      ? await Trip.find({ _id: { $in: extraIds } }).select('tripNumber patientName status scheduleType scheduleDate estimatedFare grandTotal createdAt billId').lean()
      : [];
    const linked = await payments.withReversalLinks(unbilled); // advances: not on a bill yet
    const trips = [...open, ...extra].map((t) => {
      const recs = unbilled.filter((p) => String(p.trip) === String(t._id));
      const recsJson = linked.filter((p) => String(p.trip) === String(t._id));
      const advancePaise = recs.reduce((s, p) => s + p.amountPaise, 0);
      const estimatePaise = toPaise(t.grandTotal) || toPaise(t.estimatedFare) || null;
      const reconcile = [];
      if (t.status === 'cancelled' && advancePaise) reconcile.push('advance_on_cancelled_trip');
      if (t.status === 'completed' && advancePaise) reconcile.push('advance_not_on_bill');
      if (estimatePaise && advancePaise > estimatePaise) reconcile.push('advance_above_estimate');
      return {
        _id: t._id, tripNumber: t.tripNumber, patientName: t.patientName, status: t.status,
        scheduleType: t.scheduleType, scheduleDate: t.scheduleDate, createdAt: t.createdAt,
        estimatePaise, advancePaise,
        coverRemainingPaise: estimatePaise ? Math.max(0, estimatePaise - advancePaise) : null,
        canTakeAdvance: ['booked', 'dispatched', 'en_route'].includes(t.status) && !!estimatePaise && advancePaise < estimatePaise,
        reconcile,
        payments: recsJson,
      };
    });
    return res.json({
      success: true,
      totals: { heldPaise: trips.reduce((s, t) => s + t.advancePaise, 0), tripsWithAdvance: trips.filter((t) => t.advancePaise).length },
      trips,
    });
  } catch (err) {
    next(err);
  }
};


// ============================================================
// @route   POST /api/billing/hospital-invoice/generate
// @desc    Generate (or regenerate) a monthly hospital invoice.
//
//          ALSO called by the cron job in scheduler.js at month-end.
//
//          Logic:
//          1. Find all completed trips for the hospital in the period
//             that are NOT yet included in any invoice.
//          2. Sum grandTotal of all matching bills.
//          3. Apply hospital tie-up discount.
//          4. Create / update HospitalInvoice document.
//          5. Auto-create Income entry for the net receivable.
//
// @access  Private [owner]
// ============================================================
exports.generateHospitalInvoice = async (req, res, next) => {
  try {
    const { hospitalId, month, year } = req.body;

    const m = Number(month);
    const y = Number(year);

    if (!hospitalId || !m || !y) {
      return res.status(400).json({ success: false, message: 'hospitalId, month, and year are required.' });
    }

    // ── 1. Fetch hospital and its contract terms ───────────────
    const hospital = await Hospital.findById(hospitalId);
    if (!hospital) return res.status(404).json({ success: false, message: 'Hospital not found.' });

    const discountPercent = hospital.tieUp?.discountPercent || 0;

    // ── 2. Date range ─────────────────────────────────────────
    const periodStart = new Date(y, m - 1, 1);
    const periodEnd   = new Date(y, m, 0, 23, 59, 59);

    // ── 3. Find all qualifying completed trips ─────────────────
    const trips = await Trip.find({
      dropHospital    : hospitalId,
      status          : 'completed',
      completedAt     : { $gte: periodStart, $lte: periodEnd },
      isHospitalBilled: false, // Not yet invoiced
    }).populate('billId');

    if (!trips.length) {
      return res.status(404).json({
        success: false,
        message: `No un-invoiced completed trips found for ${hospital.name} in ${m}/${y}.`,
        hospital: hospital.name,
        period  : `${m}/${y}`,
      });
    }

    // ── 4. Gather matching bills and compute totals ────────────
    const billIds    = trips.map(t => t.billId).filter(Boolean);
    const bills      = await Bill.find({ _id: { $in: billIds } });
    const grossAmount = bills.reduce((s, b) => s + (b.grandTotal || 0), 0);
    const discountAmt = Math.round(grossAmount * discountPercent / 100);
    const netPayable  = grossAmount - discountAmt;
    const dueDate     = new Date();
    dueDate.setDate(dueDate.getDate() + (hospital.tieUp?.creditDays || 30));

    const months = ['','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

    // ── 5. Upsert invoice ─────────────────────────────────────
    const invoice = await HospitalInvoice.findOneAndUpdate(
      { hospital: hospitalId, 'billingPeriod.month': m, 'billingPeriod.year': y },
      {
        hospital        : hospitalId,
        billingPeriod   : { month: m, year: y },
        trips           : trips.map(t => t._id),
        bills           : billIds,
        totalTrips      : trips.length,
        grossAmount,
        discountPercent,
        discountAmount  : discountAmt,
        netPayable,
        dueDate,
        generatedBy     : req.user?._id,
        status          : 'draft',
      },
      { upsert: true, new: true }
    );

    // ── 6. Mark trips as hospital-billed ─────────────────────
    await Trip.updateMany(
      { _id: { $in: trips.map(t => t._id) } },
      { isHospitalBilled: true, 'billId': { $exists: true } }
    );

    // Link bills to this invoice
    await Bill.updateMany(
      { _id: { $in: billIds } },
      { invoiceId: invoice._id }
    );

    // ── 7. Auto-create Income entry for net receivable ─────────
    await Income.create({
      category   : 'hospital_credit',
      amount     : netPayable,
      description: `${hospital.name} — Invoice ${invoice._id} — ${months[m]} ${y}`,
      date       : new Date(),
      invoice    : invoice._id,
      recordedBy : req.user?._id,
    });

    // ── 8. Notify owner ───────────────────────────────────────
    await Notification.create({
      type      : 'salary_generated',
      title     : `🏥 Invoice Generated: ${hospital.name}`,
      message   : `${trips.length} trips · ₹${grossAmount.toLocaleString('en-IN')} gross · ₹${netPayable.toLocaleString('en-IN')} net payable`,
      severity  : 'info',
      targetRole: 'owner',
    });

    await invoice.populate('hospital', 'name address');

    return res.status(201).json({
      success: true,
      message: `Invoice generated for ${hospital.name} — ${months[m]} ${y}`,
      invoice,
      summary: { totalTrips: trips.length, grossAmount, discountPercent, discountAmount: discountAmt, netPayable },
    });
  } catch (err) {
    next(err);
  }
};


// ============================================================
// @route   GET /api/billing/hospital-invoices
// @desc    List all hospital invoices with filters
// @access  Private [owner]
// ============================================================
exports.getHospitalInvoices = async (req, res, next) => {
  try {
    const { hospitalId, status, year, page = 1, limit = 20 } = req.query;
    const filter = {};

    if (hospitalId) filter.hospital            = hospitalId;
    if (status)     filter.status              = status;
    if (year)       filter['billingPeriod.year'] = Number(year);

    const skip  = (Number(page) - 1) * Number(limit);
    const total = await HospitalInvoice.countDocuments(filter);
    const invoices = await HospitalInvoice.find(filter)
      .populate('hospital', 'name city')
      .sort({ 'billingPeriod.year': -1, 'billingPeriod.month': -1 })
      .skip(skip)
      .limit(Number(limit));

    return res.json({ success: true, total, invoices });
  } catch (err) {
    next(err);
  }
};


// ============================================================
// @route   PUT /api/billing/hospital-invoices/:id/status
// @desc    Update invoice status (sent, paid, overdue)
// @access  Private [owner]
// ============================================================
exports.updateInvoiceStatus = async (req, res, next) => {
  try {
    const { status } = req.body;
    const update = { status };
    if (status === 'sent') update.sentAt = new Date();
    if (status === 'paid') update.paidAt = new Date();

    const invoice = await HospitalInvoice.findByIdAndUpdate(req.params.id, update, { new: true });
    if (!invoice) return res.status(404).json({ success: false, message: 'Invoice not found.' });

    return res.json({ success: true, invoice });
  } catch (err) {
    next(err);
  }
};


// ============================================================
// @route   GET /api/billing/dashboard
// @desc    Owner financial dashboard aggregation
// @access  Private [owner]
// ============================================================
// Month = the India calendar month. Billed (bills raised this month) and
// collected (money received this month) are reported apart; outstanding is
// every unpaid balance as of now (services/payments.js collectionTotals —
// the same figures as Billing and Finance).
exports.getFinancialDashboard = async (req, res, next) => {
  try {
    const { start: monthStart, end: monthEnd } = payments.istMonth();

    const [
      totals,
      invoiced,
      monthBills,
      completedTrips,
      avgFare,
      pendingInvoices,
    ] = await Promise.all([
      payments.collectionTotals({ from: monthStart, to: monthEnd }),
      payments.invoicedBills(),
      // This month's bills, for "still owed on this month's bills"
      Bill.find({ createdAt: { $gte: monthStart, $lt: monthEnd } }).select('grandTotal paidAmount paymentStatus invoiceId').lean(),
      // Trip count this month
      Trip.countDocuments({ status: 'completed', completedAt: { $gte: monthStart, $lt: monthEnd } }),
      // Average fare
      Trip.aggregate([
        { $match: { status: 'completed', completedAt: { $gte: monthStart, $lt: monthEnd } } },
        { $group: { _id: null, avg: { $avg: '$grandTotal' } } },
      ]),
      // Pending hospital invoices
      HospitalInvoice.countDocuments({ status: { $in: ['sent', 'overdue'] } }),
    ]);

    return res.json({
      success: true,
      dashboard: {
        thisMonth: {
          // Rupees, as before. collectedRevenue is now money actually
          // received this month (it was the total of bills marked paid).
          billedRevenue    : totals.billedPaise / 100,
          collectedRevenue : totals.collectedPaise / 100,
          // Recorded as received with no verified date (before itemised
          // receipts) — all-time, never part of collectedRevenue.
          collectionTimingUnverified: totals.collectionTimingUnverifiedPaise / 100,
          pendingRevenue   : monthBills.reduce((s, b) => s + payments.balanceOf(b, null, { onInvoice: invoiced.has(String(b._id)) }).collectiblePaise, 0) / 100,
          completedTrips,
          avgFare          : Math.round(avgFare[0]?.avg || 0),
        },
        outstanding        : totals.outstandingPaise / 100,   // collectible from customers
        hospitalReceivable : totals.hospital.receivablePaise / 100,
        providerPaymentsToReview: totals.providerIssues,
        advancesHeld       : totals.advancesHeldPaise / 100,
        needsReconciliation: totals.reconcileCount,
        pendingInvoices,
      },
    });
  } catch (err) {
    next(err);
  }
};
